using NUnit.Framework;using UnityEditor;using UnityEngine;using UnityEditor.AddressableAssets;using Rootborn.Game.Careers;
namespace Rootborn.Tests.EditMode.Careers{public sealed class CareerAchievementArtAssetTests{
[TestCase("Chef","chef")][TestCase("EmergencyCare","emergencycare")][TestCase("Interior","interior")][TestCase("Soldier","soldier")]
public void CompletedStageUsesReviewedTrophyAndEarlierStagesRemainUnchanged(string folder,string name){var level=AssetDatabase.LoadAssetAtPath<FacilityLevelDefinition>("Assets/Data/Careers/Facilities/"+folder+"/Level_3.asset");Assert.That(level.IsValid,Is.True);var sprite=level.AchievementSprite;Assert.That(sprite,Is.Not.Null);string path="Assets/Art/CareerFacilities/Achievements/trophy_"+name+".png";Assert.That(sprite,Is.SameAs(AssetDatabase.LoadAssetAtPath<Sprite>(path)));Assert.That(sprite.rect.size,Is.EqualTo(new Vector2(64,64)));Assert.That(sprite.pivot,Is.EqualTo(new Vector2(32,32)));Assert.That(sprite.pixelsPerUnit,Is.EqualTo(48));var i=(TextureImporter)AssetImporter.GetAtPath(path);Assert.That(i.filterMode,Is.EqualTo(FilterMode.Point));Assert.That(i.mipmapEnabled,Is.False);Assert.That(i.textureCompression,Is.EqualTo(TextureImporterCompression.Uncompressed));var entry=AddressableAssetSettingsDefaultObject.Settings.FindAssetEntry(AssetDatabase.AssetPathToGUID(path));Assert.That(entry,Is.Not.Null);Assert.That(entry.address,Is.EqualTo("sprites/career-achievements/"+name));for(int n=1;n<=2;n++)Assert.That(AssetDatabase.LoadAssetAtPath<FacilityLevelDefinition>("Assets/Data/Careers/Facilities/"+folder+"/Level_"+n+".asset").AchievementSprite,Is.Null);}
}}
